def edges_to_intersections(
    edges: T_obj_list,
    x_tolerance: T_num = 1,
    y_tolerance: T_num = 1,
) -> T_intersections:
    """
    Given a list of edges, return a dictionary of intersection points.
    """
    intersections: T_intersections = {}
    for v in filter(lambda x: x["orientation"] == "v", edges):
        for h in filter(lambda x: x["orientation"] == "h", edges):
            if (
                (v["top"] <= (h["top"] + y_tolerance))
                and (v["bottom"] >= (h["top"] - y_tolerance))
                and (h["x0"] <= (v["x0"] + x_tolerance))
                and (h["x1"] >= (v["x0"] - x_tolerance))
            ):
                vertex = (v["x0"], h["top"])
                if vertex not in intersections:
                    intersections[vertex] = {"v": [], "h": []}
                intersections[vertex]["v"].append(v)
                intersections[vertex]["h"].append(h)
    return intersections


def intersections_to_cells(intersections: T_intersections) -> List[List[T_obj]]:
    """
    Given a list of points (intersections), return a list of cells.

    This is a brute-force method of finding cells, and is O(n^2).
    """
    cells = []
    for v1, h1 in intersections:
        for v2, h2 in intersections:
            if v1 < v2 and h1 < h2:
                if (
                    (v1, h2) in intersections
                    and (v2, h1) in intersections
                ):
                    cells.append(
                        [
                            {"x0": v1, "top": h1},
                            {"x1": v2, "top": h1},
                            {"x0": v1, "bottom": h2},
                            {"x1": v2, "bottom": h2},
                        ]
                    )
    return cells


def cells_to_tables(cells: List[List[T_obj]]) -> List[List[List[T_obj]]]:
    """
    Given a list of cells, group them into tables.
    """
    def bbox(cell: List[T_obj]) -> T_bbox:
        x0 = min(map(itemgetter("x0"), cell))
        x1 = max(map(itemgetter("x1"), cell))
        top = min(map(itemgetter("top"), cell))
        bottom = max(map(itemgetter("bottom"), cell))
        return (x0, top, x1, bottom)

    def cell_in_table(cell: List[T_obj], table: List[List[T_obj]]) -> bool:
        return bbox(cell)[0] >= bbox(table[0])[0] and bbox(cell)[2] <= bbox(table[0])[2]

    tables: List[List[List[T_obj]]] = []
    for cell in cells:
        placed = False
        for table in tables:
            if cell_in_table(cell, table):
                table.append(cell)
                placed = True
                break
        if not placed:
            tables.append([cell])
    return tables


class Table(object):
    """
    A table is a list of cells, each of which is a list of four points.
    """

    def __init__(self, page: "Page", cells: List[List[T_obj]]):
        self.page = page
        self.cells = cells
        self.bbox = self._bbox()

    def _bbox(self) -> T_bbox:
        x0 = min(map(lambda c: c[0]["x0"], self.cells))
        x1 = max(map(lambda c: c[1]["x1"], self.cells))
        top = min(map(lambda c: c[0]["top"], self.cells))
        bottom = max(map(lambda c: c[2]["bottom"], self.cells))
        return (x0, top, x1, bottom)

    def extract(self, **kwargs: Any) -> List[List[Optional[str]]]:
        """
        Extract the text from the table.
        """
        return [
            [self._extract_cell(cell, **kwargs) for cell in row]
            for row in self.rows
        ]

    def _extract_cell(self, cell: List[T_obj], **kwargs: Any) -> Optional[str]:
        """
        Extract the text from a cell.
        """
        x0, top, x1, bottom = self._cell_bbox(cell)
        crop = self.page.crop((x0, top, x1, bottom))
        return crop.extract_text(**kwargs)

    def _cell_bbox(self, cell: List[T_obj]) -> T_bbox:
        x0 = min(map(itemgetter("x0"), cell))
        x1 = max(map(itemgetter("x1"), cell))
        top = min(map(itemgetter("top"), cell))
        bottom = max(map(itemgetter("bottom"), cell))
        return (x0, top, x1, bottom)

    @property
    def rows(self) -> List[List[List[T_obj]]]:
        """
        Group the cells into rows.
        """
        rows: List[List[List[T_obj]]] = []
        for cell in self.cells:
            placed = False
            for row in rows:
                if cell[0]["top"] == row[0][0]["top"]:
                    row.append(cell)
                    placed = True
                    break
            if not placed:
                rows.append([cell])
        return rows

    @property
    def row_count(self) -> int:
        return len(self.rows)

    @property
    def col_count(self) -> int:
        return len(self.rows[0]) if self.rows else 0
