package config

import (
	"context"
	"fmt"
	"sync"

	"github.com/spf13/viper"
	"k8s.io/apimachinery/pkg/api/errors"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/apimachinery/pkg/runtime"
	"k8s.io/apimachinery/pkg/runtime/schema"
	"k8s.io/client-go/tools/cache"
	"sigs.k8s.io/controller-runtime/pkg/client"

	configv1alpha1 "github.com/furiko-io/furiko/apis/config/v1alpha1"
	"github.com/furiko-io/furiko/pkg/runtime/controllerutil"
)

// ConfigManager is a manager for dynamic configuration.
type ConfigManager struct {
	client     client.Client
	namespace  string
	name       string
	config     *configv1alpha1.JobControllerConfig
	configLock sync.RWMutex
}

// NewConfigManager creates a new ConfigManager.
func NewConfigManager(client client.Client, namespace, name string) *ConfigManager {
	return &ConfigManager{
		client:    client,
		namespace: namespace,
		name:      name,
	}
}

// GetConfig returns the current configuration.
func (m *ConfigManager) GetConfig() *configv1alpha1.JobControllerConfig {
	m.configLock.RLock()
	defer m.configLock.RUnlock()
	return m.config
}

// Start starts the ConfigManager.
func (m *ConfigManager) Start(ctx context.Context) error {
	// Watch for changes to the JobControllerConfig.
	informer, err := m.getInformer(ctx)
	if err != nil {
		return err
	}

	go informer.Run(ctx.Done())
	if !cache.WaitForCacheSync(ctx.Done(), informer.HasSynced) {
		return fmt.Errorf("failed to sync informer cache")
	}

	return nil
}

func (m *ConfigManager) getInformer(ctx context.Context) (cache.SharedIndexInformer, error) {
	// Create informer for JobControllerConfig.
	gvk := schema.GroupVersionKind{
		Group:   configv1alpha1.GroupVersion.Group,
		Version: configv1alpha1.GroupVersion.Version,
		Kind:    "JobControllerConfig",
	}

	obj := &configv1alpha1.JobControllerConfig{}
	obj.SetGroupVersionKind(gvk)

	informer, err := controllerutil.NewInformer(ctx, m.client, obj, m.namespace, m.name)
	if err != nil {
		return nil, err
	}

	// Register event handlers.
	_, err = informer.AddEventHandler(cache.ResourceEventHandlerFuncs{
		AddFunc:    m.onConfigChange,
		UpdateFunc: m.onConfigUpdate,
		DeleteFunc: m.onConfigDelete,
	})
	if err != nil {
		return nil, err
	}

	return informer, nil
}

func (m *ConfigManager) onConfigChange(obj interface{}) {
	config, ok := obj.(*configv1alpha1.JobControllerConfig)
	if !ok {
		return
	}
	m.setConfig(config)
}

func (m *ConfigManager) onConfigUpdate(oldObj, newObj interface{}) {
	config, ok := newObj.(*configv1alpha1.JobControllerConfig)
	if !ok {
		return
	}
	m.setConfig(config)
}

func (m *ConfigManager) onConfigDelete(obj interface{}) {
	m.setConfig(nil)
}

func (m *ConfigManager) setConfig(config *configv1alpha1.JobControllerConfig) {
	m.configLock.Lock()
	defer m.configLock.Unlock()
	m.config = config
}

// GetDefaultPendingTimeoutSeconds returns the default pending timeout in seconds.
func (m *ConfigManager) GetDefaultPendingTimeoutSeconds() int64 {
	config := m.GetConfig()
	if config == nil {
		return 0
	}
	return config.Spec.DefaultPendingTimeoutSeconds
}

// GetDefaultTTLSecondsAfterFinished returns the default TTL after finished in seconds.
func (m *ConfigManager) GetDefaultTTLSecondsAfterFinished() int64 {
	config := m.GetConfig()
	if config == nil {
		return 0
	}
	return config.Spec.DefaultTTLSecondsAfterFinished
}

// GetDeleteKillingTasksTimeoutSeconds returns the delete killing tasks timeout in seconds.
func (m *ConfigManager) GetDeleteKillingTasksTimeoutSeconds() int64 {
	config := m.GetConfig()
	if config == nil {
		return 0
	}
	return config.Spec.DeleteKillingTasksTimeoutSeconds
}

// GetForceDeleteKillingTasksTimeoutSeconds returns the force delete killing tasks timeout in seconds.
func (m *ConfigManager) GetForceDeleteKillingTasksTimeoutSeconds() int64 {
	config := m.GetConfig()
	if config == nil {
		return 0
	}
	return config.Spec.ForceDeleteKillingTasksTimeoutSeconds
}
