// GetPendingTimeout returns the pending timeout for a Job.
func GetPendingTimeout(rj *executionv1alpha1.Job, cfg *configv1alpha1.JobControllerConfig) time.Duration {
	if rj.Spec.Template.Spec.PendingTimeoutSeconds != nil && *rj.Spec.Template.Spec.PendingTimeoutSeconds >= 0 {
		return time.Duration(*rj.Spec.Template.Spec.PendingTimeoutSeconds) * time.Second
	}
	if cfg != nil {
		return time.Duration(cfg.Spec.DefaultPendingTimeoutSeconds) * time.Second
	}
	return 0
}

// GetDeleteKillingTimeout returns the delete killing timeout for a Job.
func GetDeleteKillingTimeout(cfg *configv1alpha1.JobControllerConfig) time.Duration {
	if cfg == nil {
		return 0
	}
	return time.Duration(cfg.Spec.DeleteKillingTasksTimeoutSeconds) * time.Second
}

// GetForceDeleteKillingTimeout returns the force delete killing timeout for a Job.
func GetForceDeleteKillingTimeout(cfg *configv1alpha1.JobControllerConfig) time.Duration {
	if cfg == nil {
		return 0
	}
	return time.Duration(cfg.Spec.ForceDeleteKillingTasksTimeoutSeconds) * time.Second
}

// GetTTLAfterFinished returns the TTL after finished for a Job.
func GetTTLAfterFinished(rj *executionv1alpha1.Job, cfg *configv1alpha1.JobControllerConfig) time.Duration {
	if rj.Spec.TTLSecondsAfterFinished != nil {
		return time.Duration(*rj.Spec.TTLSecondsAfterFinished) * time.Second
	}
	if cfg != nil {
		return time.Duration(cfg.Spec.DefaultTTLSecondsAfterFinished) * time.Second
	}
	return 0
}
